function renderDimensions(p){const box=document.querySelector('#productDimensions');if(!p.dimensions){box.innerHTML='<h3>Medidas</h3><p>Por confirmar para esta referencia.</p>';return}const m=p.dimensions;const note=m.source?`Según la ficha europea del fabricante para ${m.referenceModel}. Son medidas de referencia; confirma el tamaño físico por WhatsApp si necesitas un ajuste preciso.`:'Medidas aproximadas indicadas por el vendedor. Confirma el tamaño físico por WhatsApp si necesitas un ajuste preciso.';box.innerHTML=`<h3>Medidas de referencia</h3><dl><div><dt>Alto</dt><dd>≈ ${m.heightCm} cm</dd></div><div><dt>Ancho</dt><dd>≈ ${m.widthCm} cm</dd></div><div><dt>Fondo</dt><dd>≈ ${m.depthCm} cm</dd></div></dl><p>${note}</p>${m.source?`<a href="${m.source}" target="_blank" rel="noopener noreferrer">Consultar ficha de Sprayground <span aria-hidden="true"><svg class="arrow-icon" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M6 18 18 6M6 6h12v12"/></svg></span></a>`:''}`}
const WHATSAPP_ICON="<svg class=\"whatsapp-icon\" viewBox=\"0 0 24 24\" width=\"20\" height=\"20\" fill=\"currentColor\" aria-hidden=\"true\" focusable=\"false\"><path d=\"M17.472 14.382c-.297-.149-1.758-.867-2.03-.967-.273-.099-.471-.148-.67.15-.197.297-.767.966-.94 1.164-.173.199-.347.223-.644.075-.297-.15-1.255-.463-2.39-1.475-.883-.788-1.48-1.761-1.653-2.059-.173-.297-.018-.458.13-.606.134-.133.298-.347.446-.52.149-.174.198-.298.298-.497.099-.198.05-.371-.025-.52-.075-.149-.669-1.612-.916-2.207-.242-.579-.487-.5-.669-.51-.173-.008-.371-.01-.57-.01-.198 0-.52.074-.792.372-.272.297-1.04 1.016-1.04 2.479 0 1.462 1.065 2.875 1.213 3.074.149.198 2.096 3.2 5.077 4.487.709.306 1.262.489 1.694.625.712.227 1.36.195 1.871.118.571-.085 1.758-.719 2.006-1.413.248-.694.248-1.289.173-1.413-.074-.124-.272-.198-.57-.347m-5.421 7.403h-.004a9.87 9.87 0 01-5.031-1.378l-.361-.214-3.741.982.998-3.648-.235-.374a9.86 9.86 0 01-1.51-5.26c.001-5.45 4.436-9.884 9.888-9.884 2.64 0 5.122 1.03 6.988 2.898a9.825 9.825 0 012.893 6.994c-.003 5.45-4.437 9.884-9.885 9.884m8.413-18.297A11.815 11.815 0 0012.05 0C5.495 0 .16 5.335.157 11.892c0 2.096.547 4.142 1.588 5.945L.057 24l6.305-1.654a11.882 11.882 0 005.683 1.448h.005c6.554 0 11.89-5.335 11.893-11.893a11.821 11.821 0 00-3.48-8.413Z\" /></svg>";
const WHATSAPP_PHONE='573188026232';
function whatsappLink(message){return 'https://wa.me/'+WHATSAPP_PHONE+'?text='+encodeURIComponent(message)}
function productWhatsApp(p){return whatsappLink('Hola, me interesa comprar el '+p.name+' de DISTRICT por '+money(p.price)+'. ¿Me confirmas disponibilidad, costo de envío en Medellín y medios de pago?')}
function selectionWhatsApp(){return whatsappLink('Hola, quiero consultar esta selección de DISTRICT:\n'+bag.map(id=>{const p=products.find(p=>p.id===id);return '• '+p.name+' · 1 unidad · '+money(p.price)}).join('\n')+'\nSubtotal de productos: '+money(bagTotal())+'\n¿Me confirmas disponibilidad, costo de envío en Medellín y medios de pago?')}
function updateSelectionWhatsApp(){const link=document.querySelector('#whatsappSelection');link.setAttribute('aria-disabled',String(!bag.length));if(bag.length){link.href=selectionWhatsApp();link.removeAttribute('tabindex')}else{link.removeAttribute('href');link.setAttribute('tabindex','-1')}}

const currencyFormatter=new Intl.NumberFormat('es-CO',{style:'currency',currency:'COP',maximumFractionDigits:0});
function money(value){return currencyFormatter.format(value)+' COP'}
function bagTotal(){return bag.reduce((total,id)=>total+products.find(p=>p.id===id).price,0)}
function read(k,f){try{return JSON.parse(localStorage.getItem(k))||f}catch{return f}}let bag=read('district-bag',[]).filter(id=>products.some(p=>p.id===id)),favs=read('district-favs',[]),filter='all',onlyFav=false;function persist(){try{localStorage.setItem('district-bag',JSON.stringify(bag));localStorage.setItem('district-favs',JSON.stringify(favs))}catch{}document.querySelector('#count').textContent=bag.length}function render(){
 const list=products.filter(p=>(filter==='all'||p.id===filter)&&(!onlyFav||favs.includes(p.id)));
 document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.filter===filter));
 document.querySelector('#resultCount').textContent=list.length+' '+(list.length===1?'diseño':'diseños')+(onlyFav?' en favoritos':'');
 document.querySelector('#products').innerHTML=list.length?list.map(p=>`<article><div class="card-photo"><button class="photo-button" onclick="showProduct('${p.id}')" aria-label="Explorar ${p.name}"><img src="assets/${p.photos[0]}.jpg" alt="Bolso ${p.name}" loading="lazy" width="960" height="1280"><img class="alternate-photo" src="assets/${p.photos[1]}.jpg" alt="" aria-hidden="true" loading="lazy" width="960" height="1280"><span class="card-photo-hint">Ver galería <span aria-hidden="true"><svg class="arrow-icon" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M6 18 18 6M6 6h12v12"/></svg></span></span></button><button class="heart" onclick="favorite('${p.id}')" aria-label="${favs.includes(p.id)?'Quitar':'Guardar'} ${p.name} ${favs.includes(p.id)?'de':'en'} favoritos" aria-pressed="${favs.includes(p.id)}">${favs.includes(p.id)?'♥':'♡'}</button></div><div class="card-bottom"><div><h3>${p.name}</h3><p>${p.sub}</p><p class="catalog-price">${money(p.price)}</p><p class="photo-count">Sprayground original · ${p.photos.length} fotografías</p></div><button class="card-open" onclick="showProduct('${p.id}')" aria-label="Ver detalles de ${p.name}"><span>Ver bolso</span><svg class="arrow-icon" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M6 18 18 6M6 6h12v12"/></svg></button></div><a class="product-whatsapp" href="${productWhatsApp(p)}" target="_blank" rel="noopener noreferrer" aria-label="Comprar ${p.name} por WhatsApp">${WHATSAPP_ICON}<span class="whatsapp-label">Comprar por WhatsApp</span><span aria-hidden="true"><svg class="arrow-icon" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M6 18 18 6M6 6h12v12"/></svg></span></a></article>`).join(''):`<div class="catalog-empty"><h3>${onlyFav?'Sin favoritos en esta selección':'Sin diseños en esta selección'}</h3><p>${onlyFav?'Guarda un diseño con el corazón o vuelve a explorar la colección completa.':'Prueba con otro filtro para explorar la colección.'}</p><button class="primary" onclick="resetCatalog()">Ver todos los diseños <span aria-hidden="true"><svg class="arrow-icon" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M6 18 18 6M6 6h12v12"/></svg></span></button></div>`;
}
function resetCatalog(){filter='all';onlyFav=false;document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('active',b.dataset.filter==='all'));const f=document.querySelector('#favFilter');f.classList.remove('active');f.setAttribute('aria-pressed',false);render()}
function favorite(id){favs=favs.includes(id)?favs.filter(x=>x!==id):[...favs,id];persist();render()}function showProduct(id){const p=products.find(p=>p.id===id);document.querySelector('#modalTitle').textContent=p.name;document.querySelector('#purchaseName').textContent=p.name;document.querySelector('#purchasePrice').textContent=money(p.price);renderDimensions(p);document.querySelector('#whatsappProduct').href=productWhatsApp(p);document.querySelector('#whatsappProduct').setAttribute('aria-label','Comprar '+p.name+' por WhatsApp');document.querySelector('#modalText').textContent=p.text;document.querySelector('#modalPrice').textContent=money(p.price);document.querySelector('#designInfo').textContent=p.info;setPhoto(p.photos[0],p.name);document.querySelector('#thumbnails').innerHTML=p.photos.map((photo,i)=>`<button onclick="setPhoto('${photo}','${p.name}')" aria-label="${p.name}: ${p.photoLabels[i]}"><img src="assets/${photo}.jpg" alt=""></button>`).join('');document.querySelector('#addBag').onclick=()=>{if(!bag.includes(id)){bag.push(id);persist();toast('Añadido a tu selección')}else toast('Este bolso ya está en tu selección')};document.querySelector('#productDialog').showModal();document.querySelector('.modal-scroll').scrollTop=0}function setPhoto(photo,name){const im=document.querySelector('#modalImage');im.src=`assets/${photo}.jpg`;im.alt=`${name} — ${photo==='back'?'vista posterior':photo==='detail'?'detalle de etiquetas':'vista del diseño'}`}function toast(s){const t=document.querySelector('#toast');t.textContent=s;t.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>t.classList.remove('show'),2600)}function renderBag(){document.querySelector('#cartItems').innerHTML=bag.length?bag.map(id=>{const p=products.find(x=>x.id===id);return `<div class="cart-row"><img src="assets/${p.photos[0]}.jpg" alt="${p.name}"><div><b>${p.name}</b><p class="muted">1 unidad · ${money(p.price)}</p></div><button onclick="removeBag('${id}')">Quitar</button></div>`}).join(''):'<p>Tu selección está vacía. Explora la colección y añade los diseños que te interesan.</p>';document.querySelector('#cartTotal').textContent=money(bagTotal());document.querySelector('#copySelection').disabled=!bag.length;updateSelectionWhatsApp()}function removeBag(id){bag=bag.filter(x=>x!==id);persist();renderBag()}document.querySelector('#cartOpen').onclick=()=>{renderBag();document.querySelector('#cartDialog').showModal()};document.querySelector('#copySelection').onclick=async()=>{const s='Mi selección DISTRICT — Sprayground originales:\n'+bag.map(id=>{const p=products.find(p=>p.id===id);return p.name+' · 1 unidad · '+money(p.price)}).join('\n')+'\nSubtotal: '+money(bagTotal())+'\nEntrega en Medellín: costo y disponibilidad por confirmar. Esta selección no constituye un pedido.';try{await navigator.clipboard.writeText(s);toast('Selección copiada')}catch{toast('No se pudo copiar. Selección: '+bag.map(id=>products.find(p=>p.id===id).name).join(', '))}};document.querySelector('#zoomButton').onclick=()=>{document.querySelector('#zoomed').src=document.querySelector('#modalImage').src;document.querySelector('#zoomDialog').showModal()};document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));render()});document.querySelector('#favFilter').onclick=function(){onlyFav=!onlyFav;this.classList.toggle('active',onlyFav);this.setAttribute('aria-pressed',onlyFav);render()};document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));persist();render();

// Motion and editorial interactions.
const reducedMotion=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
let galleryProduct=products[0],galleryIndex=0;
const baseShowProduct=showProduct,baseSetPhoto=setPhoto;
setPhoto=function(photo,name){baseSetPhoto(photo,name);galleryIndex=galleryProduct.photos.indexOf(photo);if(galleryIndex<0)galleryIndex=0;const img=document.querySelector('#modalImage');const caption=galleryProduct.photoLabels[galleryIndex];img.alt=`${galleryProduct.name} — ${caption}`;document.querySelector('#photoCaption').textContent=caption;if(!reducedMotion){img.classList.remove('photo-swap');void img.offsetWidth;img.classList.add('photo-swap')}document.querySelector('#photoCounter').textContent=`${String(galleryIndex+1).padStart(2,'0')} / ${String(galleryProduct.photos.length).padStart(2,'0')}`;document.querySelectorAll('#thumbnails button').forEach((b,i)=>{b.classList.toggle('selected',i===galleryIndex);b.setAttribute('aria-pressed',i===galleryIndex)});document.querySelector('#photoPrev').disabled=galleryProduct.photos.length<2;document.querySelector('#photoNext').disabled=galleryProduct.photos.length<2};
showProduct=function(id){galleryProduct=products.find(p=>p.id===id);galleryIndex=0;baseShowProduct(id);setPhoto(galleryProduct.photos[0],galleryProduct.name)};
function stepPhoto(delta){galleryIndex=(galleryIndex+delta+galleryProduct.photos.length)%galleryProduct.photos.length;setPhoto(galleryProduct.photos[galleryIndex],galleryProduct.name)}
document.querySelector('#photoPrev').onclick=()=>stepPhoto(-1);document.querySelector('#photoNext').onclick=()=>stepPhoto(1);
document.querySelector('#productDialog').addEventListener('keydown',e=>{if(document.querySelector('#zoomDialog').open)return;if(e.key==='ArrowRight'){stepPhoto(1);e.preventDefault()}if(e.key==='ArrowLeft'){stepPhoto(-1);e.preventDefault()}});
let swipeStart=0;const swipeArea=document.querySelector('#zoomButton');swipeArea.addEventListener('touchstart',e=>{swipeStart=e.changedTouches[0].clientX},{passive:true});swipeArea.addEventListener('touchend',e=>{const distance=e.changedTouches[0].clientX-swipeStart;if(Math.abs(distance)>45){stepPhoto(distance<0?1:-1);swipeArea.dataset.swiped='true';setTimeout(()=>delete swipeArea.dataset.swiped,400)}},{passive:true});const baseZoom=swipeArea.onclick;swipeArea.onclick=e=>{if(!swipeArea.dataset.swiped)baseZoom(e)};
